"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["75202"],{57624(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>h,frontMatter:()=>i,contentTitle:()=>r,toc:()=>c,assets:()=>l});var a=JSON.parse('{"id":"tangfen/abasicmathlecturetoall","title":"","description":"A problem that anyone who attended elementary school math would know about -- ordinarily it wouldn\'t warrant a dedicated main post. But I\'ve discovered that this problem isn\'t limited to just one person; it\'s actually quite widespread. People don\'t even realize they\'re wrong and are all quite self-righteous about it. So it seems this elementary math lesson must be given to such people. Let me first quote two exemplary errors:","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/abasicmathlecturetoall.md","sourceDirName":"tangfen","slug":"/tangfen/abasicmathlecturetoall","permalink":"/en/tangfen/abasicmathlecturetoall","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"abasicmathlecturetoall","title":"","hide_table_of_contents":true,"sidebar_label":"An elementary school math lesson for all people like \\"Great Demon of Democracy\\" and [Jiucai]!"},"sidebar":"tangfenSidebar","previous":{"title":"An elementary school math lesson for the likes of Yunguzhi!","permalink":"/en/tangfen/abasicmathlecture"},"next":{"title":"For the seriousness of the forum, please don\'t fabricate at will \u2014 Chirenjia Zuiduan, French Chef, and others!","permalink":"/en/tangfen/stopfaking"}}'),o=n(74848),s=n(28453);let i={id:"abasicmathlecturetoall",title:"",hide_table_of_contents:!0,sidebar_label:'An elementary school math lesson for all people like "Great Demon of Democracy" and [Jiucai]!'},r='An Elementary Math Lesson for All People Like "Democratic Grand Demon" and [Jiucai]!',l={},c=[];function u(e){let t={h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"an-elementary-math-lesson-for-all-people-like-democratic-grand-demon-and-jiucai",children:'An Elementary Math Lesson for All People Like "Democratic Grand Demon" and [Jiucai]!'})}),"\n",(0,o.jsx)(t.p,{children:"A problem that anyone who attended elementary school math would know about -- ordinarily it wouldn't warrant a dedicated main post. But I've discovered that this problem isn't limited to just one person; it's actually quite widespread. People don't even realize they're wrong and are all quite self-righteous about it. So it seems this elementary math lesson must be given to such people. Let me first quote two exemplary errors:"}),"\n",(0,o.jsxs)(t.p,{children:['In English, "uncountable" and "innumerable" do have the same meaning. From the perspective of empiricist philosophy, uncountable means innumerable. Do you understand philosophy? (Democratic Grand Demon: 2006-08-18 10:09:57)0B (0/13/1) ',(0,o.jsx)("br",{}),"\n[Jiucai] posted on 2006-08-18 13:19:12 ",(0,o.jsx)("br",{}),"\nYou can't prove that \"human thoughts\" and \"human ideas\" are countable, so just honestly admit it! Otherwise you lack academic spirit! That's what your Miss Chan said. The interval between each person's thoughts and ideas cannot be infinitely short, correct! But human thoughts and ideas cannot be quantified either, that's also a fact, right? How do you count something that can't be quantified?"]}),"\n",(0,o.jsx)(t.p,{children:'As you can see, both of the above self-righteously equate "countable" and "uncountable" with "can be enumerated" and "cannot be enumerated," and they still bring up philosophy and academics, as if they\'re not the least bit afraid of being laughed at. Truly, one grain of rice feeds a hundred kinds of people -- no surprise there.'}),"\n",(0,o.jsxs)(t.p,{children:["But in science, countable and uncountable have the strictest mathematical definitions, something known even in elementary school math: ",(0,o.jsx)("br",{}),"\nCountable: can be put in one-to-one correspondence with the natural numbers or a subset thereof. ",(0,o.jsx)("br",{}),"\nUncountable: cannot be put in one-to-one correspondence with the natural numbers or a subset thereof."]}),"\n",(0,o.jsx)(t.p,{children:'Countable versus uncountable has absolutely nothing to do with everyday "can be enumerated" or "cannot be enumerated." Just as no one can enumerate all rational numbers, yet the rational numbers are countable; just as at a time when no one could find a single transcendental number, we could already clearly prove that transcendental numbers are uncountable. Scientific concepts are not marketplace thinking. People who don\'t even know the most basic scientific concepts still talk about philosophy and academics -- is it that certain parts of their anatomy are excessively thick?'}),"\n",(0,o.jsx)(t.p,{children:"Finite necessarily implies countable -- this is also a concept known from elementary school math. Why? Because finite necessarily corresponds one-to-one with some subset of the natural numbers. But countable does not necessarily mean finite, just as the rational numbers mentioned above are countable but infinite. These issues have nothing to do with Miss Chan's proof; they are all the most basic scientific concepts. Please stop making a laughingstock of yourselves!"})]})}function h(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u(e)}},28453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var a=n(96540);let o={},s=a.createContext(o);function i(e){let t=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);